+function formatDate(date, timezone = 'UTC') {
+  // Convert to the requested timezone before formatting
+  const utc = date.getTime() + (date.getTimezoneOffset() * 60000);
+  const tzDate = new Date(utc + (3600000 * timezoneOffset(timezone)));
+  return tzDate.toISOString().split('T')[0];
+}
+
+function timezoneOffset(tz) {
+  // Simple static map for a few common zones; fallback to 0 (UTC)
+  const offsets = { 'UTC': 0, 'EST': -5, 'PST': -8 };
+  return offsets[tz] || 0;
+}
